-- Task 9.1 (users and ownership). Generated by drizzle-kit, then edited by hand:
-- SQLite can't add a NOT NULL column without a default to a table with rows,
-- so the four tables are rebuilt and every existing row is given to user 1.
-- There is deliberately no `DEFAULT 1`: code that forgets the owner must fail.
-- `migrate()` (db/index.ts) runs this in one transaction with foreign keys
-- off and runs `foreign_key_check` before commit. The server takes a backup
-- before migrating (backup/pre-migrate.ts).
CREATE TABLE `users` (
	`id` integer PRIMARY KEY AUTOINCREMENT NOT NULL,
	`username` text NOT NULL,
	`password_hash` text,
	`role` text NOT NULL,
	`can_create_api_keys` integer NOT NULL,
	`totp_secret` text,
	`disabled_at` text,
	`created_at` text NOT NULL,
	`last_login_at` text
);
--> statement-breakpoint
CREATE UNIQUE INDEX `users_username_unique` ON `users` (`username`);--> statement-breakpoint
-- Every install has user 1, the admin of local mode. Everything from before belongs to it.
INSERT INTO `users` (`id`, `username`, `role`, `can_create_api_keys`, `created_at`)
	VALUES (1, 'admin', 'admin', 1, strftime('%Y-%m-%dT%H:%M:%fZ', 'now'));--> statement-breakpoint
CREATE TABLE `__new_api_keys` (
	`id` integer PRIMARY KEY AUTOINCREMENT NOT NULL,
	`user_id` integer NOT NULL,
	`created_by_user_id` integer NOT NULL,
	`revoked_by_user_id` integer,
	`name` text NOT NULL,
	`key_hash` text NOT NULL,
	`prefix` text NOT NULL,
	`created_at` text NOT NULL,
	`last_used_at` text,
	`revoked_at` text,
	FOREIGN KEY (`user_id`) REFERENCES `users`(`id`) ON UPDATE no action ON DELETE no action,
	FOREIGN KEY (`created_by_user_id`) REFERENCES `users`(`id`) ON UPDATE no action ON DELETE no action,
	FOREIGN KEY (`revoked_by_user_id`) REFERENCES `users`(`id`) ON UPDATE no action ON DELETE no action
);
--> statement-breakpoint
INSERT INTO `__new_api_keys` (`id`, `user_id`, `created_by_user_id`, `revoked_by_user_id`, `name`, `key_hash`, `prefix`, `created_at`, `last_used_at`, `revoked_at`)
	SELECT `id`, 1, 1, CASE WHEN `revoked_at` IS NOT NULL THEN 1 END, `name`, `key_hash`, `prefix`, `created_at`, `last_used_at`, `revoked_at` FROM `api_keys`;--> statement-breakpoint
-- Keep the AUTOINCREMENT counter, so an ID is never handed out twice.
UPDATE `sqlite_sequence` SET `seq` = (SELECT `seq` FROM `sqlite_sequence` WHERE `name` = 'api_keys')
	WHERE `name` = '__new_api_keys' AND EXISTS (SELECT 1 FROM `sqlite_sequence` WHERE `name` = 'api_keys');--> statement-breakpoint
DROP TABLE `api_keys`;--> statement-breakpoint
ALTER TABLE `__new_api_keys` RENAME TO `api_keys`;--> statement-breakpoint
CREATE UNIQUE INDEX `api_keys_key_hash_unique` ON `api_keys` (`key_hash`);--> statement-breakpoint
CREATE INDEX `api_keys_user_idx` ON `api_keys` (`user_id`);--> statement-breakpoint
CREATE TABLE `__new_events` (
